document.addEventListener("DOMContentLoaded",()=>{const s=e=>{const t=e.closest("tr");if(!t)return;const r=t.querySelector("[data-mobile-meta]");r&&(e.checked?(r.classList.remove("grid-rows-[0fr]"),r.classList.add("grid-rows-[1fr]")):(r.classList.remove("grid-rows-[1fr]"),r.classList.add("grid-rows-[0fr]")))};document.querySelectorAll('input[name="work_ids"]').forEach(e=>s(e)),document.addEventListener("change",e=>{const t=e.target;t instanceof HTMLInputElement&&t.name==="work_ids"&&s(t)})});
